package damage.engine.client;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Tracks entities the local player recently attacked (melee or projectile).
 * Used by ClientHealthTracker to filter out damage not caused by the player
 * in client-only mode (server without the mod).
 */
public class ClientAttackTracker {
    private static final ClientAttackTracker INSTANCE = new ClientAttackTracker();

    private final Map<Integer, Long> recentAttacks = new ConcurrentHashMap<>();

    private static final long ATTACK_MEMORY_MS = 2000;

    public static ClientAttackTracker getInstance() {
        return INSTANCE;
    }

    public void recordAttack(int entityId) {
        recentAttacks.put(entityId, System.currentTimeMillis());
    }

    public boolean wasRecentlyAttacked(int entityId) {
        Long time = recentAttacks.get(entityId);
        if (time == null) return false;
        if (System.currentTimeMillis() - time > ATTACK_MEMORY_MS) {
            recentAttacks.remove(entityId);
            return false;
        }
        return true;
    }

    public void cleanup() {
        long now = System.currentTimeMillis();
        recentAttacks.entrySet().removeIf(e -> now - e.getValue() > ATTACK_MEMORY_MS);
    }
}

package damage.engine.client;

import damage.engine.DamageEngineClient;
import damage.engine.DamageEngineConfig;
import damage.engine.hud.indicator.DamageIndicator;
import damage.engine.hud.session.DamageSessionManager;
import net.minecraft.client.Minecraft;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.phys.EntityHitResult;
import net.minecraft.world.phys.Vec3;

/**
 * Client-side health tracker that detects damage by monitoring entity health changes.
 * Only active when the server does NOT have Damage Engine installed (client-only mode).
 * 
 * Limitations in client-only mode:
 * - Cannot identify attacker (cannot filter for player's own damage)
 * - Cannot detect critical hits
 * - Cannot detect projectile vs. melee attacks
 * - Damage indicator position is approximate (entity position)
 */
public class ClientHealthTracker {

    /**
     * Called by the client mixin when a living entity's health or absorption changes.
     * Only processes damage when in confirmed client-only mode.
     */
    public static void onEntityDamaged(LivingEntity entity, float damageAmount, boolean killed) {
        if (!DamageEngineClient.serverModChecked || DamageEngineClient.serverHasMod) {
            return;
        }

        DamageEngineConfig config = DamageEngineConfig.getInstance();
        if (!config.showDamage) return;

        // Check if player recently attacked this entity
        boolean isSelfDamage = ClientAttackTracker.getInstance().wasRecentlyAttacked(entity.getId());

        // Handle global damage indicators (damage caused by others)
        if (!isSelfDamage && config.showGlobalDamageIndicator) {
            // Calculate distance for culling
            Minecraft client = Minecraft.getInstance();
            if (client.player != null) {
                // 分项设置:玩家使用玩家显示距离,非玩家实体按实体规则(注册名/All)
                Float maxDist = config.resolveGlobalIndicatorDistance(entity);
                if (maxDist == null) {
                    return; // 该受害实体被屏蔽或未配置显示
                }
                double dx = entity.getX() - client.player.getX();
                double dy = entity.getY() - client.player.getY();
                double dz = entity.getZ() - client.player.getZ();
                double distance = Math.sqrt(dx * dx + dy * dy + dz * dz);

                if (maxDist <= 0 || distance <= maxDist) {
                    Vec3 pos = DamageEngineClient.blendIndicatorPos(
                        entity.getX(),
                        entity.getY() + entity.getEyeHeight() * 0.6,
                        entity.getZ(),
                        entity.getId()
                    );

                    if (config.showDamageIndicator && damageAmount > 0) {
                        DamageIndicator.addIndicator(entity, pos.x, pos.y, pos.z,
                            damageAmount,
                            false,  // Cannot detect crit in client-only mode
                            false
                        );
                    }

                    if (config.showKillIndicator && killed) {
                        DamageIndicator.addIndicator(entity, pos.x, pos.y, pos.z,
                            damageAmount,
                            false,
                            true
                        );
                    }
                }
            }
            return; // Don't process further for global damage
        }

        // Only track damage for entities the player recently attacked (melee or projectile)
        if (!isSelfDamage) {
            return;
        }

        // 准星命中的实体交给会话判断(末影龙需从部件映射到本体),命中时强制切换信息面板目标
        Minecraft client = Minecraft.getInstance();
        Entity crosshair = client.hitResult instanceof EntityHitResult ehr ? ehr.getEntity() : null;
        // 没有准心实体（远程/爆炸等）：直接切换到本次受伤的目标
        boolean preferSwitchTarget = crosshair == null
            || DamageSessionManager.isSameVictim(crosshair, entity.getId());

        float distance = client.player != null
            ? damage.engine.hud.rating.CombatContext.distance(client.player, entity) : 0f;
        boolean unseen = killed && client.player != null
            && damage.engine.hud.rating.CombatContext.isHiddenFromPlayer(entity, client.player);
        DamageSessionManager.getInstance().addDamage(damageAmount, false, entity.getId(),
            preferSwitchTarget, killed, distance, unseen);

        // Blend indicator position toward crosshair hit point
        Vec3 pos = DamageEngineClient.blendIndicatorPos(
            entity.getX(),
            entity.getY() + entity.getEyeHeight() * 0.6,
            entity.getZ(),
            entity.getId()
        );

        // Add damage indicator using blended position, capped by the configured max distance
        if (client.player != null) {
            double maxDist = config.globalIndicatorMaxDistance;
            if (maxDist <= 0 || pos.distanceToSqr(client.player.position()) <= maxDist * maxDist) {
                if (config.showDamageIndicator && damageAmount > 0) {
                    DamageIndicator.addIndicator(entity, pos.x, pos.y, pos.z,
                        damageAmount,
                        false,  // Cannot detect crit in client-only mode
                        false
                    );
                }

                if (config.showKillIndicator && killed) {
                    DamageIndicator.addIndicator(entity, pos.x, pos.y, pos.z,
                        damageAmount,
                        false,
                        true
                    );
                }
            }
        }
    }
}

package damage.engine.mixin.client;

import damage.engine.client.ClientHealthTracker;
import damage.engine.DamageEngineClient;
import damage.engine.DamageEngineConfig;
import damage.engine.hud.indicator.DamageIndicator;
import net.minecraft.client.Minecraft;
import net.minecraft.world.entity.LivingEntity;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Unique;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/**
 * Client-side mixin that monitors LivingEntity health changes.
 * Runs on every tick for living entities in the client world.
 * Only feeds data to ClientHealthTracker when in client-only mode.
 */
@Mixin(LivingEntity.class)
public class LivingEntityClientMixin {
    @Unique
    private float tracker$lastHealth = 0;
    @Unique
    private float tracker$lastAbsorption = 0;
    @Unique
    private boolean tracker$initialized = false;
    @Unique
    private long tracker$lastDamageTime = 0;

    @Inject(method = "tick", at = @At("TAIL"))
    private void onTickClientSide(CallbackInfo ci) {
        LivingEntity self = (LivingEntity) (Object) this;
        if (!self.level().isClientSide()) return;
        // Target dummies recharge their health before it reaches the client, so health
        // diffs are meaningless for them. Their damage numbers come from
        // DummyDamageCompat via the dummy mod's own message instead.
        if (self.getClass().getName().startsWith("net.mehvahdjukaar.dummmmmmy.")) return;

        float h = self.getHealth();
        float a = self.getAbsorptionAmount();

        if (!tracker$initialized) {
            tracker$lastHealth = h;
            tracker$lastAbsorption = a;
            tracker$initialized = true;
            return;
        }

        float healthLost = tracker$lastHealth - h;
        float absorptionLost = tracker$lastAbsorption - a;
        float actualDamage = healthLost + absorptionLost;

        boolean killed = !self.isAlive() && (tracker$lastHealth > 0 || tracker$lastAbsorption > 0);

        // Only process damage when server does NOT have the mod (client-only mode).
        // When server has the mod, the server sends DamagePayload and we must NOT
        // also add indicators from the health tracker to avoid double indicators.
        if ((actualDamage > 0.001f || killed) && !DamageEngineClient.serverHasMod) {
            // Deduplication: skip if damage was detected within the last 50ms for the same entity.
            // This prevents duplicate indicators from rapid health syncs.
            long now = System.currentTimeMillis();
            if (now - tracker$lastDamageTime > 50) {
                float reportedDamage = killed ? Math.max(actualDamage, 0) : actualDamage;
                ClientHealthTracker.onEntityDamaged(self, reportedDamage, killed);
                tracker$lastDamageTime = now;
            }
        }

        // Detect healing (health increase) - show globally for all entities
        if (h > tracker$lastHealth + 0.001f) {
            float healAmount = h - tracker$lastHealth;
            DamageEngineConfig config = DamageEngineConfig.getInstance();
            if (config.showDamage && config.showHealIndicator) {
                // Check distance for culling
                Minecraft client = Minecraft.getInstance();
                if (client.player != null && client.level != null) {
                    double dx = self.getX() - client.player.getX();
                    double dy = self.getY() - client.player.getY();
                    double dz = self.getZ() - client.player.getZ();
                    double distance = Math.sqrt(dx * dx + dy * dy + dz * dz);

                    // For heal indicators, use the indicator distance (0 = unlimited)
                    float maxDistance = config.globalIndicatorMaxDistance;
                    if (maxDistance <= 0 || distance <= maxDistance) {
                        double posX = self.getX();
                        double posY = self.getY() + self.getEyeHeight() * 0.6;
                        double posZ = self.getZ();
                        DamageIndicator.addIndicator(self, posX, posY, posZ, healAmount, false, false, true);
                    }
                }
            }
        }

        tracker$lastHealth = h;
        tracker$lastAbsorption = a;
    }
}

package damage.engine.mixin.client;

import damage.engine.ClientKeybindings;
import damage.engine.DamageEngineConfig;
import damage.engine.DamageEngineClient;
import damage.engine.client.ClientAttackTracker;
import damage.engine.client.gui.HomeScreen;
import damage.engine.hud.session.DamageSessionManager;
import damage.engine.hud.indicator.DamageIndicator;
import net.minecraft.client.Minecraft;
import net.minecraft.network.chat.Component;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/**
 * Replaces Fabric API's ClientTickEvents.END_CLIENT_TICK with a direct mixin.
 */
@Mixin(Minecraft.class)
public class ClientTickMixin {

    @Inject(method = "tick", at = @At("TAIL"))
    private void damageEngine$onEndClientTick(CallbackInfo ci) {
        Minecraft client = (Minecraft) (Object) this;

        if (client.player != null) {
            if (DamageEngineClient.joinCheckTicks > 0) {
                DamageEngineClient.joinCheckTicks--;
                if (DamageEngineClient.joinCheckTicks == 0) {
                    if (!DamageEngineClient.serverModChecked) {
                        if (client.getSingleplayerServer() != null) {
                            DamageEngineClient.serverHasMod = true;
                        } else {
                            DamageEngineClient.serverHasMod = false;
                        }
                        DamageEngineClient.serverModChecked = true;
                    }
                }
            }

            DamageEngineConfig config = DamageEngineConfig.getInstance();
            if (!config.hasShownWelcomeMessage) {
                client.player.sendSystemMessage(
                    Component.translatable("text.damage-engine.welcome_message").withColor(0xB1EAC2)
                );
                config.hasShownWelcomeMessage = true;
                config.save();
            }

            if (ClientKeybindings.configKeyBinding != null) {
                while (ClientKeybindings.configKeyBinding.consumeClick()) {
                    client.setScreen(new HomeScreen(client.screen));
                }
            }
            if (ClientKeybindings.toggleHudKeyBinding != null) {
                while (ClientKeybindings.toggleHudKeyBinding.consumeClick()) {
                    config.showDamage = !config.showDamage;
                    config.save();
                }
            }
            if (ClientKeybindings.clearDamageKeyBinding != null) {
                while (ClientKeybindings.clearDamageKeyBinding.consumeClick()) {
                    DamageSessionManager.getInstance().reset();
                    DamageIndicator.clearAll();
                }
            }
        }

        if (!client.isPaused()) {
            DamageSessionManager.getInstance().tick();
            DamageIndicator.tickAndCleanup();
            ClientAttackTracker.getInstance().cleanup();
        }
    }
}

package damage.engine.mixin.client;

import damage.engine.client.ClientAttackTracker;
import net.minecraft.client.Minecraft;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/**
 * Tracks the local player's melee attacks so ClientHealthTracker can filter
 * for damage actually caused by the player in client-only mode.
 */
@Mixin(Player.class)
public class PlayerAttackMixin {
    @Inject(method = "attack", at = @At("HEAD"))
    private void damageEngine$onAttack(Entity target, CallbackInfo ci) {
        Player self = (Player) (Object) this;
        if (self == Minecraft.getInstance().player && target != null) {
            ClientAttackTracker.getInstance().recordAttack(target.getId());
        }
    }
}

package damage.engine.mixin.client;

import damage.engine.client.ClientAttackTracker;
import net.minecraft.client.Minecraft;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.phys.EntityHitResult;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

/**
 * Tracks projectile hits for projectiles owned by the local player,
 * so ClientHealthTracker can filter for damage actually caused by the player.
 */
@Mixin(Projectile.class)
public class ProjectileHitMixin {
    @Inject(method = "onHitEntity", at = @At("HEAD"))
    private void damageEngine$onHitEntity(EntityHitResult hitResult, CallbackInfo ci) {
        Projectile self = (Projectile) (Object) this;
        Entity owner = self.getOwner();
        Entity target = hitResult.getEntity();
        if (owner != null && owner == Minecraft.getInstance().player && target != null) {
            ClientAttackTracker.getInstance().recordAttack(target.getId());
        }
    }
}

package damage.engine.client;

import net.minecraft.client.Minecraft;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

/**
 * Resolves the world position where a floating damage indicator should spawn.
 *
 * <p>For hits caused by the player (e.g. TaCZ gunfire) the indicator should anchor
 * at the exact point the crosshair hit (foot, head, ...), not at the entity center
 * and not at the server-reported projectile position (which is unreliable: TaCZ
 * bullets can report a position at the shooter, and the clamped Y lands around the
 * torso).</p>
 *
 * <p>{@link Minecraft#hitResult} cannot be used because its pick ray is limited to
 * the survival reach (~6 blocks), far shorter than gun range. Instead we cast a long
 * ray from the player's eye along the current view vector and take its entry point
 * into the victim's bounding box.</p>
 */
public final class IndicatorPos {
    /** Ray length used for crosshair hit-point resolution (well beyond gun range). */
    private static final double RAY_RANGE = 512.0;
    /** Slight AABB inflation to mimic the projectile's collision box. */
    private static final double AABB_INFLATE = 0.2;

    private IndicatorPos() {}

    /**
     * @param baseX baseY baseZ server-reported fallback position (victim-side hit point)
     * @param entityId id of the damaged entity (client-level lookup for the crosshair ray)
     * @return the crosshair hit point on the victim, or the fallback position if it
     *         cannot be resolved
     */
    public static Vec3 blend(double baseX, double baseY, double baseZ, int entityId) {
        Minecraft client = Minecraft.getInstance();
        if (client.level == null || client.player == null) {
            return new Vec3(baseX, baseY, baseZ);
        }
        Entity target = client.level.getEntity(entityId);
        if (target != null) {
            Vec3 hit = crosshairHitPoint(client, target);
            if (hit != null) {
                return hit;
            }
        }
        return new Vec3(baseX, baseY, baseZ);
    }

    private static Vec3 crosshairHitPoint(Minecraft client, Entity target) {
        Vec3 eye = client.player.getEyePosition(1.0F);
        Vec3 look = client.player.getViewVector(1.0F);
        Vec3 end = eye.add(look.scale(RAY_RANGE));
        AABB box = target.getBoundingBox().inflate(AABB_INFLATE);
        return box.clip(eye, end).orElse(null);
    }
}

public DamageEngineClient(IEventBus modEventBus, ModContainer modContainer) {
    // 1.21.11: KeyMapping uses Category instead of a category string
